css:
.showcase__tab {
  display: flex;
  align-items: center;
  gap: clamp(8px, 0.7vw, 14px);
  color: rgb(255 255 255 / 0.28);
  font-size: clamp(12px, 0.82vw, 15px);
  font-weight: 500;
  line-height: 1;
  white-space: nowrap;
  cursor: default;
  user-select: none;
  transition: color 320ms ease;
}
